// Category B: no behaviour beyond keeping focus clear of itself. The bottom twin of SiteHeader: a
// full-width bar fixed to the bottom of the viewport, on the page's own fill with an edge above it,
// whose content stops at the page grid's frame. It owns the look a docked bottom bar needs, which a
// Block may not set, and keeps the device's bottom safe area clear below its content. A bar that
// floats inset over the page instead is Card `variant="raised"` (the BottomNav Block).
import type { CSSProperties, HTMLAttributes, Ref } from "react";
import { useScrollClearance } from "./useScrollClearance";
import "./DockedBar.css";

export interface DockedBarProps extends Omit<HTMLAttributes<HTMLDivElement>, "className"> {
  /**
   * How wide the bar is from the `breakpoint` step up. `full` spans the window at every width.
   * `constrained` docks full width below the step and, from it, floats centred at the window's bottom
   * as a raised card narrower than the page column, so a conversion bar stays in reach on a wide
   * screen without reading as page chrome.
   *
   * @default "full"
   */
  width?: "full" | "constrained";
  /**
   * The step from which a `constrained` bar floats. Match the AppShell's `breakpoint` it sits in.
   *
   * @default "medium"
   */
  breakpoint?: "medium" | "large";
  /**
   * The room above and below the content while the bar is docked. `medium` keeps a bar of controls
   * off its edge and the window's bottom. `none` is for content that pads itself to its own height,
   * as a tab bar does (BottomNavDocked); the device's safe area is still cleared below. A
   * `constrained` bar floating from its step pads on its card's inset either way.
   *
   * @default "medium"
   */
  padding?: "medium" | "none";
  className?: string;
  style?: CSSProperties;
  ref?: Ref<HTMLDivElement>;
}

/**
 * One CSS knob is public: `--sd-docked-bar-offset`, how far above the window's bottom edge the bar
 * docks (0 by default). A frame stacking the bar over another bottom bar sets it to that bar's reach,
 * as AppShell's `bottomBar` slot does above its tab bar; the device's safe area is then cleared only
 * by what the bar still covers.
 */
export function DockedBar({ width = "full", breakpoint = "medium", padding = "medium", className, children, ref, ...props }: DockedBarProps) {
  // The bar covers the bottom of the page, so the document keeps focus clear of it (WCAG 2.4.11).
  const clearRef = useScrollClearance("end", ref);

  return (
    <div
      {...props}
      ref={clearRef}
      data-width={width}
      data-breakpoint={breakpoint}
      className={className ? `sd-docked-bar ${className}` : "sd-docked-bar"}
    >
      {/* The frame reacts to the width too, so it carries the attributes itself (§6 rule 2). */}
      <div className="sd-docked-bar__frame" data-width={width} data-breakpoint={breakpoint} data-padding={padding}>
        {children}
      </div>
    </div>
  );
}

/* DockedBar.css — .sd-docked-bar (+ __frame)
   A full-width bar fixed to the bottom of the viewport, on the page's own fill with a decorative edge
   above. The frame takes the page grid's margin and cap, like SiteHeader's, the bar's block padding,
   like StickyBar's, and the device's bottom safe area (reported only under `viewport-fit=cover`; 0
   otherwise).
   `--sd-docked-bar-offset` is the public knob DockedBar.tsx documents: it INHERITS from the frame
   that stacks the bar (AppShell's `bottomBar` slot sets it inline), so it is declared `inherit`
   here rather than reset, and reads 0 where nothing sets it. */
.sd-docked-bar {
  --sd-docked-bar-offset: inherit;
  position: fixed;
  inset-inline: 0;
  inset-block-end: var(--sd-docked-bar-offset, 0px);
  z-index: var(--sd-docked-bar-z-index);
  background: var(--sd-docked-bar-background);
  border-block-start: var(--sd-docked-bar-border-width) solid var(--sd-docked-bar-border);
}

/* The content clears the edge above and the window's bottom by the padding. Stacked over another bar, only the part of the safe area that bar
   leaves uncovered is added below: under a tab bar, none, or the inset is padded twice. */
.sd-docked-bar__frame {
  max-inline-size: var(--sd-docked-bar-max-width);
  margin-inline: auto;
  padding-inline: var(--sd-docked-bar-padding-inline);
  padding-block-start: var(--sd-docked-bar-padding-block);
  padding-block-end: calc(var(--sd-docked-bar-padding-block) + max(0px, calc(env(safe-area-inset-bottom) - var(--sd-docked-bar-offset, 0px))));
}
/* `padding="none"`: content that sizes itself, a tab bar, keeps its own height; only the safe area is
   cleared. The constrained rules below are more specific, so a floating bar keeps its card's inset. */
.sd-docked-bar__frame[data-padding="none"] {
  padding-block-start: 0;
  padding-block-end: max(0px, calc(env(safe-area-inset-bottom) - var(--sd-docked-bar-offset, 0px)));
}

/* Constrained, from its step up: a raised card floating centred over the page's foot, narrower than
   the column, a margin off the window's bottom edge. It pads all round on the surface pair, and the
   safe area is the margin's to clear. */
@media (min-width: 768px) {
  .sd-docked-bar[data-width="constrained"]:not([data-breakpoint="large"]) {
    inset-block-end: calc(var(--sd-docked-bar-offset, 0px) + var(--sd-docked-bar-float-margin));
    inline-size: min(var(--sd-docked-bar-float-width), calc(100% - 2 * var(--sd-docked-bar-float-margin)));
    margin-inline: auto;
    border: var(--sd-docked-bar-border-width) solid var(--sd-docked-bar-border);
    border-radius: var(--sd-docked-bar-float-radius);
    corner-shape: superellipse(var(--sd-radius-curve));
    box-shadow: var(--sd-docked-bar-float-shadow);
  }
  .sd-docked-bar__frame[data-width="constrained"]:not([data-breakpoint="large"]) {
    max-inline-size: none;
    padding: var(--sd-docked-bar-float-padding);
  }
}

@media (min-width: 1024px) {
  .sd-docked-bar[data-width="constrained"][data-breakpoint="large"] {
    inset-block-end: calc(var(--sd-docked-bar-offset, 0px) + var(--sd-docked-bar-float-margin));
    inline-size: min(var(--sd-docked-bar-float-width), calc(100% - 2 * var(--sd-docked-bar-float-margin)));
    margin-inline: auto;
    border: var(--sd-docked-bar-border-width) solid var(--sd-docked-bar-border);
    border-radius: var(--sd-docked-bar-float-radius);
    corner-shape: superellipse(var(--sd-radius-curve));
    box-shadow: var(--sd-docked-bar-float-shadow);
  }
  .sd-docked-bar__frame[data-width="constrained"][data-breakpoint="large"] {
    max-inline-size: none;
    padding: var(--sd-docked-bar-float-padding);
  }
}
